practice.solution:
n = int(input())
for i in range(1, n + 1):
    c = int(input())
    m = int(input())
    b = int(input())
    if c**2 != m * c + b:
        print(f"problem {i}: jump, not differentiable")
    elif 2 * c == m:
        print(f"problem {i}: differentiable, f'({c}) = {m}")
    else:
        print(f"problem {i}: corner, slopes {2 * c} and {m}")
